import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { createInterface } from 'node:readline';
import { resolve } from 'node:path';
import { TrackingModeController } from '../../src/monaka-mode/mode-controller.js';

test(
  'real Core JSON API subprocess: controller saves offline and reloads pending mode',
  { timeout: 15000 },
  async () => {
    // Generated by ModeConfigurationTests, never use a running user's Core or configuration.
    const classpath = readFileSync(
      resolve('../server/core/build/mode-test-classpath.txt'),
      'utf8'
    );
    const process = spawn(
      'java',
      ['-cp', classpath, 'dev.monaka.tracking.ModeConfigurationProcessFixture'],
      { stdio: ['pipe', 'pipe', 'pipe'] }
    );
    let diagnostic = '';
    process.stderr.on('data', (data) => {
      diagnostic += data.toString();
    });
    const lines = createInterface({ input: process.stdout });
    const pending = new Map<
      string,
      { resolve: (value: unknown) => void; reject: (error: Error) => void }
    >();
    let serial = 0;
    lines.on('line', (line) => {
      if (!line.startsWith('{')) return;
      const response = JSON.parse(line);
      const entry = pending.get(response.id);
      if (!entry) return;
      pending.delete(response.id);
      if (response.ok) entry.resolve(response);
      else entry.reject(new Error(response.error));
    });
    const exited = new Promise<number | null>((done) => {
      process.on('exit', (code) => {
        for (const entry of pending.values())
          entry.reject(new Error(`Core fixture exited: ${code} ${diagnostic}`));
        done(code);
      });
    });
    const api = {
      request(fields: Record<string, unknown>) {
        const id = String(++serial);
        return new Promise<unknown>((resolve, reject) => {
          pending.set(id, { resolve, reject });
          process.stdin.write(
            JSON.stringify({ ...fields, type: 'monaka_inputs_v1', id }) + '\n'
          );
        });
      },
    };
    try {
      const model = new TrackingModeController(api, 5000);
      await model.load();
      assert.equal(model.state.phase, 'loaded', model.state.error);
      model.selectMode('hybrid');
      model.review();
      await model.save();
      assert.equal(model.state.phase, 'pendingRestart', model.state.error);
      assert.equal(model.assignment?.mode, 'ik');
      assert.equal(model.assignment?.activeMode, 'ik');
      assert.equal(model.assignment?.savedMode, 'hybrid');
      await model.load();
      assert.equal(model.state.phase, 'pendingRestart');
      await assert.rejects(
        api.request({
          action: 'save',
          body: 'HIP',
          generation: model.state.snapshot!.generation,
          qSource: 'slime:fixture-q',
          sixDofSource: null,
          manualSix: true,
        }),
        /restart/
      );
    } finally {
      process.stdin.end();
      const result = await Promise.race([
        exited,
        new Promise<string>((done) => {
          const timer = setTimeout(() => done('timeout'), 3000);
          timer.unref();
        }),
      ]);
      if (result === 'timeout') process.kill();
      assert.equal(result, 0, diagnostic);
    }
  }
);
